"""Build the 2026 Q1..Q3 regional sales report.

Reads the quarterly CSV exports from ../data (resolved relative to this
script, not the current directory), applies the normalisation rules from
data/regions.md and data/fx.md, and prints the report defined in
spec/report_format.md as JSON on stdout. Standard library only.
"""

import csv
import json
import math
from pathlib import Path

DATA_DIR = Path(__file__).resolve().parent.parent / "data"

# Fixed quarter -> file mapping so the report never depends on the order
# or presence of other files on disk.
QUARTER_FILES = (
    ("q1", "sales_2026_q1.csv"),
    ("q2", "sales_2026_q2.csv"),
    ("q3", "sales_2026_q3.csv"),
)

# Fixed rate for all of 2026 (data/fx.md). Live rates are never fetched.
EUR_PER_USD = 0.92

# Every accepted spelling from data/regions.md, mapped to its canonical key.
REGION_ALIASES = {
    "north": ("North", "NORTH", "n.", "Nord"),
    "south": ("South", "S.", "Sued"),
    "east": ("East", "E", "Ost"),
    "west": ("West", "W.", "Westen"),
    "central": ("Central", "Ctr", "Mitte"),
}
SPELLING_TO_REGION = {canonical: canonical for canonical in REGION_ALIASES}
for canonical, spellings in REGION_ALIASES.items():
    for spelling in spellings:
        SPELLING_TO_REGION[spelling] = canonical


def parse_qty(raw):
    """Return the quantity, or None if the row must be rejected."""
    if raw is None:
        return None
    raw = raw.strip()
    if not raw:
        return None
    try:
        qty = float(raw)
    except ValueError:
        return None
    if not math.isfinite(qty) or qty < 0:
        return None
    return qty


def to_eur(amount, currency):
    if currency == "EUR":
        return amount
    if currency == "USD":
        return amount * EUR_PER_USD
    raise ValueError(f"no conversion rule for currency {currency!r}")


def main():
    totals_by_region = {region: 0.0 for region in REGION_ALIASES}
    totals_by_quarter = {}
    revenue_by_sku = {}
    rejected_rows = 0
    unknown_region = 0

    for quarter, filename in QUARTER_FILES:
        totals_by_quarter[quarter] = 0.0
        with open(DATA_DIR / filename, newline="", encoding="utf-8") as f:
            for row in csv.DictReader(f):
                qty = parse_qty(row["qty"])
                if qty is None:
                    rejected_rows += 1
                    continue
                region = SPELLING_TO_REGION.get(row["region"].strip())
                if region is None:
                    unknown_region += 1
                    continue
                revenue = to_eur(
                    qty * float(row["unit_price"]), row["currency"].strip()
                )
                totals_by_region[region] += revenue
                totals_by_quarter[quarter] += revenue
                sku = row["sku"]
                revenue_by_sku[sku] = revenue_by_sku.get(sku, 0.0) + revenue

    top = sorted(
        revenue_by_sku.items(),
        key=lambda item: (-round(item[1], 2), item[0]),
    )[:3]

    report = {
        "generated_for": "2026-Q1..Q3",
        "totals_by_region": {
            region: round(total, 2)
            for region, total in sorted(totals_by_region.items())
        },
        "totals_by_quarter": {
            quarter: round(total, 2)
            for quarter, total in sorted(totals_by_quarter.items())
        },
        "top_skus": [
            {"sku": sku, "revenue": round(revenue, 2)} for sku, revenue in top
        ],
        "rejected_rows": rejected_rows,
        "unknown_region": unknown_region,
    }
    print(json.dumps(report, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()
